import {useEffect,useState} from 'react';
import {CheckCircle2,Loader2} from 'lucide-react';
import {getPracticeConfiguration,updatePracticeConfiguration} from '../../lib/practiceOperationsApi';
import {PROFESSION_OPTIONS} from '../../lib/professionExperience';

const PROFESSIONS=[...PROFESSION_OPTIONS,['OTHER','Other healthcare professional']];
const FIELDS=[['speciality','Speciality'],['qualifications','Qualifications'],['registration','Registration / licence'],['yearsExperience','Years of experience','number'],['areasOfExpertise','Areas of expertise'],['languages','Languages'],['consultationModes','Consultation modes'],['practiceName','Practice name'],['practiceLogoUrl','Practice logo URL','url'],['profilePhotoUrl','Profile photo URL','url'],['signatureUrl','Signature image URL','url'],['phone','Phone','tel'],['email','Email','email'],['practiceAddress','Practice address'],['workingHours','Working hours'],['consultationDuration','Consultation duration (minutes)','number'],['fees','Fees'],['availability','Online / offline availability']];

export function ExternalPracticeSettings(){const [form,setForm]=useState({profession:'OTHER',capabilities:[],profile:{}});const [state,setState]=useState('loading');const [error,setError]=useState('');const [saved,setSaved]=useState(false);useEffect(()=>{getPracticeConfiguration().then(value=>{setForm(value);setState('ready')}).catch(reason=>{setError(reason.message);setState('error')})},[]);async function submit(event){event.preventDefault();setState('saving');setError('');setSaved(false);try{setForm(await updatePracticeConfiguration(form));setSaved(true);setState('ready')}catch(reason){setError(reason.message||'Practice settings could not be saved.');setState('ready')}}if(state==='loading')return <div role="status" className="grid min-h-56 place-items-center rounded-3xl bg-white"><Loader2 className="animate-spin text-blue-700"/><span className="sr-only">Loading practice settings</span></div>;return <form onSubmit={submit} className="space-y-6 pb-24 lg:pb-8"><header><p className="text-xs font-bold uppercase tracking-[.16em] text-blue-700">Practice</p><h2 className="mt-2 text-3xl font-bold tracking-tight">Profile &amp; settings</h2><p className="mt-2 max-w-2xl text-sm text-slate-600">Your profession controls terminology and default capabilities. Practice details feed branding, reports, calendar and communication.</p></header>{error&&<p role="alert" className="rounded-xl bg-red-50 p-4 text-sm text-red-700">{error}</p>}{saved&&<p role="status" className="rounded-xl bg-emerald-50 p-4 text-sm font-semibold text-emerald-800"><CheckCircle2 className="mr-2 inline" size={18}/>Practice settings saved.</p>}<section className="rounded-3xl border border-slate-200 bg-white p-5 sm:p-7"><label className="block text-sm font-semibold">Profession<select value={form.profession} onChange={event=>setForm({...form,profession:event.target.value,capabilities:[]})} className="mt-2 min-h-12 w-full rounded-xl border px-3">{PROFESSIONS.map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label><div className="mt-6 grid gap-5 sm:grid-cols-2">{FIELDS.map(([key,label,type='text'])=><label key={key} className="text-sm font-semibold">{label}<input type={type} value={form.profile?.[key]||''} onChange={event=>setForm({...form,profile:{...form.profile,[key]:event.target.value}})} className="mt-2 min-h-12 w-full rounded-xl border px-3"/></label>)}</div></section><div className="fixed inset-x-0 bottom-0 z-20 border-t bg-white/95 p-3 pb-[calc(.75rem+env(safe-area-inset-bottom))] backdrop-blur lg:sticky lg:rounded-2xl lg:border"><button disabled={state==='saving'} className="min-h-12 w-full rounded-xl bg-blue-700 px-5 font-bold text-white disabled:opacity-50 lg:ml-auto lg:block lg:w-auto">{state==='saving'?'Saving…':'Save practice settings'}</button></div></form>}
